from author_library import *
cards=[]
cards.append(compact('tianjia','天嘉土王','天嘉土王在一个保留王族制度的国家掌权，财富与地位都很可观，却始终受到传统考验和同族竞争的威胁。他宁可冒险进入从来没有人成功返回的山洞，也害怕把王位直接交给全民选择，因此求卫斯理作助手，又不断被这个助手对权力的讥刺激怒。考验前，卫斯理坚持试吹号角揭穿教长的圈套，他马上用公开展示证物和提升其他教职者的办法稳住局面，显出真正的政治手腕。进入洞中后，他才明白所谓天神考验实质关系民众意向，从此施政有所改变，获得更多拥护。然而《只限老友》中急剧恶化的脑癌把一切特权推到极限：勒曼医院准备了备用身体，却无法把他的思想移出原身，他转而追寻齐白和思想仪的线索。医院借其复制身体和天神名义进入山洞的行动，没有治好他本人。他最终仍然死亡，继任王位未交代。卡片必须保留他曾学会敬畏民意的变化，也保留临死时不愿失去权力与生命的恐惧；复制体的巨大力量和医院技术都不属于他。','《只限老友》换体失败、脑癌病逝；部署恢复最后尚能交谈决策的本人病体','主角','延续生命与王位，并维持经过考验后更重视的国家稳定','习惯命令与礼遇，但在危难中能承认需要专家帮助','权位受威胁时迅速调整利益分配；生命受威胁时穷尽求助渠道','权力依赖民众和现实支持，财富并不能保证任何奇迹成功',[ab('政治应变','通过公开证据、职位调整和利益平衡稳定政局','仅对实际承认其职位的人有作用，不是精神控制'),ab('资源与特殊医疗联系','拥有联系勒曼医院和委托调查的财力与渠道','思想转移在本人身上失败；备用身体不是第二条已完成的生命')],[ev('121',2771,2855,'识破阴谋后的应变'),ev('121',3138,3227,'民意考验与通过'),ev('145',163,183,'施政变化和病况'),ev('145',213,243,'备用身体与失败前提'),ev('145',1229,1243,'最终死亡')],profile='ordinary',extra={'weaknesses':['终局严重癌症限制活动；恢复可行动接口不消除疾病。','思想不能离体，勒曼常规换体技术在他身上没有成功。'],'adaptations':[{'change':'部署恢复死前尚能交谈决策的本人身体，不采用医院控制的空白复制体。','reason':'本人已亡而复制体没有承继人格。','power_impact':'不获得复制体力量，不获得换体成功或免死。'}]}))
cards.append(compact('hai_gao','海高','海高是天嘉土王的王族竞争者，在族中有相当威望，长期等待对方王位松动的机会。他围绕传统考验布置人手，关注卫斯理是否协助土王，也试图用自己掌握的立场影响外来者。对他而言，王位不是抽象的家族荣誉，而是可以通过优势人数、传统解释和关键时机夺取的现实目标。第一次考验前，土王与卫斯理争执，他在人群中幸灾乐祸地大笑；教长阴谋被揭穿、土王最终成功返回，使希望落空。到《只限老友》，天嘉长期不露面，他得到对方出事的迹象，带着更多支持者再度等待发动。亮声等人借天神之名护送复制体出现，并轻易搬动巨石展示远超常人的力量，海高无法应对，追随者大半转向另一边，他顿时手足无措。这个结局没有说明他后来是否真的继位，也没有证明他同教长之间每一项串谋细节。卡片只保留可确认的争位行动与政治弱点：他善等机会，却把人群的投机支持看得过于稳定；一旦象征权威和实力共同倒向对手，自己的把握便迅速瓦解。','《只限老友》争位现场遭外星力量展示压倒，支持者大量离散；后续是否继位未交代','反派','取得土王之位并扩大自己在王族中的控制权','监视竞争者的弱点，保持体面与威望，累积支持','对手虚弱时积极布阵；实际力量超出预期时会失去节奏','人数与传统只是条件，追随者会随力量和利益改变站位',[ab('王族结盟与时机判断','利用亲族威望、情报和公开场合争夺政治优势','不具备已证实的超常个人战力；终局原支持者已大幅流失')],[ev('121',1149,1182,'王位竞争及支持背景'),ev('121',2748,2751,'幸灾乐祸的实际表现'),ev('145',1076,1104,'再次布阵和对手力量'),ev('145',1124,1135,'支持瓦解')],profile='ordinary'))
cards.append(compact('jiaozhang','天嘉国的原教长','原教长掌握天嘉国传统仪式中的关键位置，平时不轻易见人，披红色长袍，由人抬行，围绕自身制造神秘与尊严。天嘉土王自以为同他关系很好，认为考验时可以信任他，却没有意识到仪式本身就提供了置人于死地的机会。教长交给土王一支号角，以隐藏的小型扬声设备伪装它能够发声；如果土王按规矩进入山洞后无法吹响，就可能再也无法出来。面对卫斯理提出试吹，他以冷森森的牛津腔讥讽，想激起土王的怒气，让对方拒绝这项检查。计划偏偏败在土王了解卫斯理的坚持，盛怒中仍试了号角。骗局当众暴露，教长失去支持，只能脱下红袍交出设备，被警卫带走，后续具体刑罚没有交代。卡片不因为宗教身份赋予他任何神术，也不把可怕声响写成自身音波攻击。他的危险来自把程序、权威和熟人信任拧成一个不允许检验的陷阱，而同样明确的弱点是无法承受简单公开的实物测试。','《考验》阴谋暴露、被撤去教长身份并由警卫带走，后续生死未交代','反派','借仪式控制权影响王位更替，维护自身权力','维持神秘距离，以冷淡姿态和标准英语增加压迫感','有人要求检验关键道具时激怒对方，试图阻止正常核验','其优势来自别人不敢质疑的程序；证物一旦公开，权威迅速失效',[ab('仪式欺骗与暗藏扬声设备','用袖下装置播放号角声，掩盖实物不能吹响的事实','设备被收缴；不是法术，也不能保证新环境的人相信其职位'),ab('教职权力','曾指挥仪式中的人手并掌握传统流程','终局已被罢黜，旧部没有跟随反抗')],[ev('121',2603,2635,'仪式位置与神秘形象'),ev('121',2729,2797,'讥讽与骗术被揭穿'),ev('121',2816,2851,'交出设备、被捕及撤职')],profile='ordinary',aliases=['教长']))
cards.append(compact('royal_elder','天嘉王族的年长代表','这位没有具名的王族长者代表许多族人，关注土王是否依照传统接受考验，也派人观察可能改变结果的卫斯理。他不是披着红袍主持仪式的教长，两人的身份和行为必须分开。他在飞机上被质问时保持优雅和冷静，声称既不拥护也不反对天嘉，只希望按规矩办事；这份中立实际上仍以王族延续统治为前提。他懂得现代政治，有三所大学的博士头衔，其中包括政治学，能够指出天嘉宁愿冒生命危险也不愿把权位交给全民决定。更值得注意的是，他并不假装自己置身其外：卫斯理问为何不推动改革，他坦然承认一旦改革，自己的地位也要接受选择，所以同样害怕。卡片把这种清醒与自保并存的性格作为核心，而不是写成愚昧祭司。他能理解反对意见，却未因此愿意承担改革的代价。终局未记载他离开王族体制或个人死亡，保留其知识、协调与守成倾向；他所代表的支持者必须在具体场景里存在，不能自动成为随身部队。','《考验》仍为王族年长代表，未交代后续个人生死或改革行动','阶段性对立者','维持王族传统和自身可预期的地位','以礼貌、教育背景和程序解释化解质问','既得地位被直接挑战时坦然承认恐惧，但不主动放弃权力','理解问题不等于愿意改变，选择总要联系其个人代价',[ab('政治分析与协调','具现代政治知识，能够代表族中多方分析权位变化','知识不等于公正立场，也没有超常控制人心能力')],[ev('121',1113,1136,'身份、监视与程序立场'),ev('121',1165,1201,'政治学历和自保坦白')],profile='expert',aliases=['王族老者']))
cards.append(compact('yu_fang','于放','于放是以拼命和善于夜战闻名的将军，出身大凉山，以狩猎和艰苦生活练就灵敏身手。赛观音叙述两人相识时，他不会成套武术，却能在极暗环境下占到优势；有关夜视的具体机制主要来自她的讲述，铁旦能佐证的是他确实擅长夜战与夜行军，不能把这种能力扩成穿墙透视。他带着抗敌的理想向土匪喊话，强烈的语言打动许多人，又同赛观音经历数日斗智与搏斗，从对手成为伴侣。后来战事留下独眼独臂和累累伤痕，他仍把一生交给自己相信的组织，却最终被同一组织折磨至死。妻子拒绝划清关系，与女儿一同受苦，死后平反也无法归还他的生命。终局卡若用于演绎，应明确恢复的是负伤后的最后可行动人身，保留得知结局后的复杂感受，而不是把他重新包装成毫无怀疑的口号机器。对理想的忠诚、对战友的信任和亲眼见过的背叛可以同时存在，新的选择需要现场发生，不能替他先写好彻底转向或继续盲从的唯一答案。','《偷天换日》回忆中遭政治迫害死亡，后获平反；部署恢复终局负伤人身','主角','保卫所认同的人民与理想，并守住与妻子和战友的承诺','在行军和困难环境中务实果断，能够用强烈信念鼓舞别人','战斗时敢承担风险，遇到己方权力侵害应面对事实而非自动否认','对共同理想的忠诚不能免除组织行为的审视',[ab('夜战与野外行动','从狩猎生活积累夜间行动经验，战史中多次善用夜袭','夜视细节为赛观音口述，不能认定无限黑暗视觉、穿墙或远视'),ab('军事实践与动员','经历多次战斗，善用喊话和心理影响争取对方','终局缺眼缺臂限制身体，旧部不自动恢复')],[ev('134',50,50,'负伤、独眼独臂'),ev('134',144,150,'婚姻与迫害死亡'),ev('134',601,645,'动员、搏斗和夜视证据边界')],profile='investigator',extra={'appearance':{'description':'后期独眼独臂，身上有多次战斗留下的伤；不默默恢复完整身体。','portrayal':'行动果决，谈理想时有感染力，面对背叛允许出现沉默与复杂情绪。'},'adaptations':[{'change':'恢复死前可行动形态，保留已知后续命运，允许重新审视忠诚对象。','reason':'已亡历史人物的互动接口与用户终局知识要求。','power_impact':'不修复战争残伤，不增加超出文本的夜视范围。'}]}))
save(cards)
